import { homedir } from "node:os";
import { join } from "node:path";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import YAML from "yaml";

export const ROOT = join(import.meta.dir, "..");
export const DATA_DIR = process.env.CU_HUB_DATA ?? join(homedir(), ".cu-hub");
export const PROFILE_DIR = join(DATA_DIR, "browser-profile");
export const COOKIES_FILE = join(DATA_DIR, "cookies.json");
export const DB_FILE = join(DATA_DIR, "hub.sqlite");
export const RULES_DIR = join(ROOT, "rules");
/** Rules generated by the setup wizard from LMS data; override rules/*.yaml with the same lms_id. */
export const USER_RULES_DIR = join(DATA_DIR, "rules");

mkdirSync(USER_RULES_DIR, { recursive: true });

export const LMS_ORIGIN = "https://my.centraluniversity.ru";

export interface CourseLink {
  label: string;
  url: string;
}

/** Per-course local overrides layered over rules/*.yaml and LMS data. Keyed by LMS course id. */
export interface CourseOverride {
  title?: string;
  short?: string;
  color?: string;
  syllabusUrl?: string;
  timeUrl?: string;
  /** extra materials: repo, drive, recordings, ... */
  links?: CourseLink[];
  /** extra calendar title patterns (regex), added to rules calendar.match */
  calendarMatch?: string[];
}

export interface CaldavConfig {
  url: string;
  username: string;
  /** macOS Keychain service name holding the app password */
  keychainService: string;
  /** calendar display names to read; empty = all */
  calendars?: string[];
}

export interface HubConfig {
  workspaceRoot: string;
  webPort: number;
  syncIntervalMin: number;
  /** Monday of academic week 1; defaults to rules/_academic.yaml */
  semesterStart?: string;
  caldav?: CaldavConfig;
  reminders: { beforeClassMin: number; digestAt: string; weeklyReviewAt: string };
  courses: Record<string, CourseOverride>;
  /** set by the setup wizard; unset for installs that predate it */
  setupDone?: boolean;
  /** LMS course ids to track; unset = every course that has rules */
  trackedCourses?: number[];
  agent?: {
    /** path to the claude CLI; autodetected when empty */
    claudeBin?: string;
    /** tools the background draft agent may use without asking */
    allowedTools?: string[];
    maxTurns?: number;
  };
}

const DEFAULTS: HubConfig = {
  workspaceRoot: join(homedir(), "study"),
  webPort: 4321,
  syncIntervalMin: 30,
  reminders: { beforeClassMin: 40, digestAt: "08:00", weeklyReviewAt: "Sun 20:00" },
  courses: {},
};

export const CONFIG_FILE = join(DATA_DIR, "config.yaml");

function readUser(): Partial<HubConfig> {
  if (!existsSync(CONFIG_FILE)) return {};
  return YAML.parse(readFileSync(CONFIG_FILE, "utf8")) ?? {};
}

export function loadConfig(): HubConfig {
  const user = readUser();
  return {
    ...DEFAULTS,
    ...user,
    workspaceRoot: (user.workspaceRoot ?? DEFAULTS.workspaceRoot).replace(/^~/, homedir()),
    webPort: Number(process.env.CU_HUB_PORT) || user.webPort || DEFAULTS.webPort,
    reminders: { ...DEFAULTS.reminders, ...(user.reminders ?? {}) },
    courses: user.courses ?? {},
  };
}

export function courseOverride(lmsId: number): CourseOverride {
  return loadConfig().courses[String(lmsId)] ?? {};
}

const listeners = new Set<() => void>();
export function onConfigChange(fn: () => void) {
  listeners.add(fn);
}

/** Shallow-merge a patch into the user's config.yaml. `null` removes a key. */
export function saveConfig(patch: Partial<Record<keyof HubConfig, unknown>>) {
  const user: Record<string, unknown> = { ...readUser() };
  for (const [k, v] of Object.entries(patch)) {
    if (v === null) delete user[k];
    else if (v !== undefined) user[k] = v;
  }
  writeFileSync(CONFIG_FILE, YAML.stringify(user), { mode: 0o600 });
  for (const fn of listeners) fn();
}

const KEYCHAIN_DEFAULT = "cu-hub-caldav";
export { KEYCHAIN_DEFAULT };

/**
 * MCP server entry for .mcp.json files. Absolute bun path: Claude desktop and Finder-launched sessions
 * do not read the shell profile, so ~/.bun/bin is not on their PATH.
 */
export function mcpServerEntry() {
  const env = process.env.CU_HUB_DATA ? { env: { CU_HUB_DATA: DATA_DIR } } : {};
  return { command: process.execPath, args: [join(ROOT, "src/mcp/server.ts")], ...env };
}

/** The project's own .mcp.json: generated per machine, not committed. A custom CU_HUB_DATA leaves it alone. */
export function writeProjectMcp() {
  if (process.env.CU_HUB_DATA) return;
  writeFileSync(join(ROOT, ".mcp.json"), JSON.stringify({ mcpServers: { "cu-hub": mcpServerEntry() } }, null, 2) + "\n");
}
